with months as (select distinct date_trunc('month', date_day)::date as stat_month from {{ ref('time_spine') }}), month_ends as (select stat_month, (stat_month + interval 1 month - interval 1 day)::date as month_end from months), elig as (select c.member_id, m.stat_month from {{ ref('cards') }} c cross join month_ends m where c.card_type in ('悦享年卡','家庭季卡') and c.valid_from <= m.month_end and c.valid_until > m.month_end and (c.ended_at is null or c.ended_at > m.month_end) group by c.member_id, m.stat_month), agg as (select member_id, stat_month, valid_order_cnt, sum(paid_cents - refund_cents) as net_sales_cents from (select member_id, date_trunc('month', ordered_at)::date as stat_month, paid_cents, refund_cents from {{ ref('member_purchase_seq') }}) t group by member_id, stat_month, count(*) over () valid_order_cnt_placeholder select null) select 1